#include <bits/stdc++.h>
using namespace std;
using ll = long long;

class DinicAlgorithm {
public:
    struct Edge {
        int to;
        int rev;
        ll cap;
    };

    int N;
    vector<vector<Edge>> g;
    vector<int> level, iter;
    int s, t;

    DinicAlgorithm(int n, int src, int dst) : N(n), g(n), level(n), iter(n), s(src), t(dst) {}

    void addEdge(int u, int v, ll c) {
        g[u].emplace_back(Edge{v, (int)g[v].size(), c});
        g[v].emplace_back(Edge{u, (int)g[u].size()-1, 0});
    }

    bool bfs() {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        q.push(s);
        level[s] = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (const auto& e : g[u]) {
                if (e.cap > 0 && level[e.to] == -1) {
                    level[e.to] = level[u] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[t] != -1;
    }

    ll dfs(int u, ll f) {
        if (u == t) return f;
        for (int &i = iter[u]; i < (int)g[u].size(); ++i) {
            Edge &e = g[u][i];
            if (e.cap > 0 && level[e.to] == level[u] + 1) {
                ll pushed = dfs(e.to, min(f, e.cap));
                if (pushed > 0) {
                    e.cap -= pushed;
                    g[e.to][e.rev].cap += pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    ll maxFlow() {
        ll result = 0;
        while (bfs()) {
            fill(iter.begin(), iter.end(), 0);
            ll pushed;
            while ((pushed = dfs(s, 1LL << 60)) > 0) {
                result += pushed;
            }
        }
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, T;
    cin >> n >> T;

    vector<string> grid(n);
    int zy = -1, zx = -1;
    for (int i = 0; i < n; ++i) {
        cin >> grid[i];
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == 'Z') {
                zy = i; zx = j;
            }
        }
    }

    string dummy;
    getline(cin, dummy);
    getline(cin, dummy);

    vector<string> exits(n);
    for (int i = 0; i < n; ++i) {
        cin >> exits[i];
    }

    vector<vector<int>> dist(n, vector<int>(n, -1));
    queue<pair<int, int>> q;
    q.push({zy, zx});
    dist[zy][zx] = 0;

    const int dy[] = {1, -1, 0, 0};
    const int dx[] = {0, 0, 1, -1};

    while (!q.empty()) {
        auto [y, x] = q.front(); q.pop();
        for (int d = 0; d < 4; ++d) {
            int ny = y + dy[d], nx = x + dx[d];
            if (ny < 0 || ny >= n || nx < 0 || nx >= n) continue;
            if (dist[ny][nx] != -1 || grid[ny][nx] == 'Y') continue;
            dist[ny][nx] = dist[y][x] + 1;
            if (dist[ny][nx] < T) {
                q.push({ny, nx});
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] >= '0' && grid[i][j] <= '9') {
                if (dist[i][j] == -1) dist[i][j] = T;
                else dist[i][j] = min(dist[i][j], T);
            }
        }
    }

    vector<vector<int>> nodeId(n, vector<int>(n, -1));
    int nodeCount = 0;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] >= '0' && grid[i][j] <= '9') {
                nodeId[i][j] = nodeCount++;
            }
            if (exits[i][j] >= '1' && exits[i][j] <= '9') {
                nodeId[i][j] = nodeCount++;
            }
        }
    }

    int src = 0, dst = nodeCount + 1;
    DinicAlgorithm flow(nodeCount + 2, src, dst);

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] >= '1' && grid[i][j] <= '9') {
                flow.addEdge(src, nodeId[i][j], grid[i][j] - '0');
            }

            if (exits[i][j] >= '1' && exits[i][j] <= '9') {
                flow.addEdge(nodeId[i][j], dst, exits[i][j] - '0');
            }

            for (int d = 0; d < 4; ++d) {
                int ni = i + dy[d], nj = j + dx[d];
                if (ni < 0 || ni >= n || nj < 0 || nj >= n) continue;
                if (grid[ni][nj] == 'Y' || grid[ni][nj] == 'Z') continue;

                if (nodeId[i][j] != -1 && nodeId[ni][nj] != -1) {
                    flow.addEdge(nodeId[i][j], nodeId[ni][nj], 1000000000);
                }
            }
        }
    }

    cout << flow.maxFlow() << '\n';
    return 0;
}
